const expected = $env.N8N_WEBHOOK_SECRET || '';
const received = $json.headers?.['x-safarni-webhook-secret'] || '';
if (expected && received !== expected) {
  throw new Error('Unauthorized SAFARNI webhook request');
}
return items;

const data = $json;
const itineraries = Array.isArray(data.itineraries) ? data.itineraries : [];
const legs = Array.isArray(data.legs) ? data.legs : [];
const segments = Array.isArray(data.segments) ? data.segments : [];
const carriers = Array.isArray(data.carriers) ? data.carriers : [];
const carrierMap = new Map(carriers.map(c => [String(c.id), c]));
const limit = Math.min(Math.max(Number($('Search Parameters').first().json.limit || 5), 1), 10);
const nonstopOnly = Boolean($('Search Parameters').first().json.nonstop_only);
const requestedCurrency = String($('Search Parameters').first().json.currency || 'USD');
const results = [];

for (const itinerary of itineraries) {
  const legId = itinerary.leg_ids?.[0];
  const leg = legs.find(l => l.id === legId);
  if (!leg) continue;
  const itinerarySegments = (leg.segment_ids || []).map(id => segments.find(s => s.id === id)).filter(Boolean);
  const pricing = itinerary.pricing_options?.[0];
  const price = pricing?.price || itinerary.cheapest_price || {};
  const amount = Number(price.amount);
  if (!Number.isFinite(amount)) continue;
  results.push({
    itinerary_id: itinerary.id,
    price: amount,
    currency: data.currency || requestedCurrency,
    price_status: price.update_status || null,
    quote_age_minutes: price.quote_age ?? null,
    departure: leg.departure || null,
    arrival: leg.arrival || null,
    duration_minutes: leg.duration ?? null,
    stops: leg.stop_count ?? null,
    segments: itinerarySegments.map(s => ({
      flight_number: s.marketing_flight_number || null,
      departure: s.departure || null,
      arrival: s.arrival || null,
      duration_minutes: s.duration ?? null,
      marketing_carrier_id: s.marketing_carrier_id ?? null,
      operating_carrier_id: s.operating_carrier_id ?? null,
      marketing_carrier: carrierMap.get(String(s.marketing_carrier_id)) || null
    })),
    booking_url: pricing?.items?.[0]?.url || null
  });
}

const eligible = nonstopOnly ? results.filter(f => Number(f.stops) === 0) : results;
eligible.sort((a, b) => a.price - b.price);
return eligible.slice(0, limit).map((flight, index) => ({ json: { rank: index + 1, ...flight } }));
